SELECT departments.dept_name, CASE WHEN departments.budget >= 4398000 THEN 'high' WHEN departments.budget >= 625000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(DISTINCT employees.salary) AS unique_depts, MAX(employees.salary) - MIN(employees.salary) AS salary_range FROM employees INNER JOIN departments ON employees.dept_id = departments.id GROUP BY departments.dept_name, CASE WHEN departments.budget >= 4398000 THEN 'high' WHEN departments.budget >= 625000 THEN 'mid' ELSE 'low' END ORDER BY salary_range DESC, dept_name, budget_bucket LIMIT 10;
